// Names over tall looks (O433 phase 5, track Q): the engine puts a creature's name and health bar from the dat alone (a little over the top of its
// 32 x 32 cell, up by the displacement), so on a look drawn taller than the stock ones the name fell across the face or the chest. The main client
// lifts them per look type (client_chaos_infolift, base patch 0111, table generated from the pair by client/tools/sprites/gen_info_lift.py). Unity
// reads the same table (InfoLiftData.cs, generated by unity/tools/gen_info_data.lua) and moves the name and bar of a PLAYER or an NPC up by the lift
// (sprite pixels at 1x, 32 to a tile); monsters keep the classic place, as in the main client.
using System;
using System.Collections.Generic;

namespace Chaos.Core
{
    public static class InfoLift
    {
        /// <summary>The cap of the engine (Creature::setInformationLift).</summary>
        public const int Max = 96;

        static Dictionary<int, int> map;

        static Dictionary<int, int> Map
        {
            get
            {
                if (map == null) map = Entries(InfoLiftData.Table);
                return map;
            }
        }

        /// <summary>The valid {look, lift} pairs of a flat table (look, lift, look, lift ...): a look of 1 or more with a lift above 0, capped at Max.</summary>
        public static Dictionary<int, int> Entries(int[] flat)
        {
            var o = new Dictionary<int, int>();
            if (flat == null) return o;
            for (int i = 0; i + 1 < flat.Length; i += 2)
                if (flat[i] >= 1 && flat[i + 1] > 0) o[flat[i]] = Math.Min(Max, flat[i + 1]);
            return o;
        }

        /// <summary>The lift of one look type in sprite pixels (0: none).</summary>
        public static int Of(int look) { int v; return Map.TryGetValue(look, out v) ? v : 0; }

        /// <summary>The lift of a creature: players and NPCs wearing a look type; monsters, summons and items shown as an outfit have none.</summary>
        public static int For(Creature c)
        {
            if (c == null || (c.Type != 0 && c.Type != 2) || c.Outfit == null || c.Outfit.LookType <= 0) return 0;
            return Of(c.Outfit.LookType);
        }

        /// <summary>The lift in UI units for a map drawn tile pixels tall (a tile is 32 sprite pixels).</summary>
        public static float Scaled(Creature c, float tile) => For(c) * tile / 32f;

        /// <summary>Phase 8 B: the lift for the view in use. The HD-2D and live views put a name at the top of the figure they draw (Hd2dView.Label.Head), so the look's table must not
        /// lift it again; the classic view places names from the dat alone and needs it.</summary>
        public static float ForView(Creature c, float tile, bool headFromFigure) => headFromFigure ? 0f : Scaled(c, tile);

        public static int Count => Map.Count;
    }
}
